using System.Text;

namespace Invoicing;

/// <summary>Renders an invoice to a plain-text document.</summary>
public sealed class InvoiceRenderer
{
    public string Render(Invoice invoice, Account account)
    {
        var sb = new StringBuilder();

        AppendHeader(sb, invoice, account);
        var (net, vat) = AppendInvoiceLines(sb, invoice);
        AppendTotals(sb, net, vat, account.Kind);
        AppendPaymentTerms(sb, account.Kind);

        return sb.ToString();
    }

    private static void AppendHeader(StringBuilder sb, Invoice invoice, Account account)
    {
        sb.AppendLine($"INVOICE {invoice.Number}");
        if (account.Name.Length > 0)
            sb.AppendLine(account.Name);

        switch (account.Kind)
        {
            case AccountKind.Business:
                sb.AppendLine("VAT registered");
                break;
            case AccountKind.Government:
                sb.AppendLine("Government purchase order");
                break;
            case AccountKind.Consumer:
                sb.AppendLine("Consumer");
                break;
        }
    }

    private static (decimal Net, decimal Vat) AppendInvoiceLines(StringBuilder sb, Invoice invoice)
    {
        decimal net = 0m, vat = 0m;
        foreach (var line in invoice.Lines)
        {
            if (line.NetAmount < 0m)
                continue;

            decimal lineVat = line.NetAmount * line.VatRate;
            if (line.VatRate == 0m)
                sb.AppendLine($"{line.Description} {line.NetAmount} (zero-rated)");
            else if (line.VatRate >= 0.2m)
                sb.AppendLine($"{line.Description} {line.NetAmount} (std {lineVat})");
            else
                sb.AppendLine($"{line.Description} {line.NetAmount} (reduced {lineVat})");

            net += line.NetAmount;
            vat += lineVat;
            if (line.Description.Length > 40)
                sb.AppendLine("  (description truncated)");
        }

        return (net, vat);
    }

    private static void AppendTotals(
        StringBuilder sb,
        decimal net,
        decimal vat,
        AccountKind accountKind)
    {
        decimal discount = 0m;
        if (net > 1000m && accountKind == AccountKind.Business)
            discount = net * 0.05m;
        else if (net > 5000m)
            discount = net * 0.10m;

        var gross = net + vat - discount;
        if (gross < 0m)
            gross = 0m;

        sb.AppendLine($"NET {net} VAT {vat} DISC {discount} TOTAL {gross}");
    }

    private static void AppendPaymentTerms(StringBuilder sb, AccountKind accountKind)
    {
        if (accountKind == AccountKind.Government)
            sb.AppendLine("Remit within 30 days");
        else
            sb.AppendLine("Remit within 14 days");
    }
}
